    public static final IdentifierName ServiceOperation = identifierStr(runCleanup);

    public static void main(Args _args)
    {
        AVADAIReportCleanupController controller = new AVADAIReportCleanupController(classStr(AVADAIReportCleanupService), methodStr(AVADAIReportCleanupService, runCleanup), classStr(AVADAIReportCleanupContract));
        controller.parmShowDialog(true);
        controller.parmCaption("AVADAI Report Export Work Cleanup");
        controller.startOperation();
    }

    protected void new(IdentifierName _className = ServiceClass, IdentifierName _methodName = ServiceOperation, IdentifierName _dataContract = classStr(AVADAIReportCleanupContract))
    {
